import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { markComplete, deleteTask } from "../State/action-creators/index";
import "../Style/DisplayAllTasks.css";
import TaskCard from "./TaskCard";
import SelectBox from "./SelectBox";
import searchbtn from './assets/searchbtn.png';

function DisplayAllTasks() {
  const dispatch = useDispatch();
  const tasks = useSelector((state) => state.tasks);

  const [searchInputName, setSearchInputName] = useState(""); // Title input
  const [searchCategory, setSearchCategory] = useState("");   // Category select
  const [searchPriority, setSearchPriority] = useState("");   // Priority select
  const [filteredTasks, setFilteredTasks] = useState(tasks);  // Tasks to display

  // ✅ Apply filters when search button is clicked
  const handleSearchClick = () => {
    const trimmedInput = searchInputName.trim().toLowerCase();

    const results = tasks.filter((task) => {
      const matchesCategory = searchCategory === "" || task.Category === searchCategory;
      const matchesPriority = searchPriority === "" || task.Priorty === searchPriority;
      const matchesTitle =
        trimmedInput === "" || task.title.toLowerCase().includes(trimmedInput);

      return matchesCategory && matchesPriority && matchesTitle;
    });

    setFilteredTasks(results);
  };

  // ✅ Reset filters and show all tasks
  const handleResetFilters = () => {
    setSearchInputName("");
    setSearchCategory("");
    setSearchPriority("");
    setFilteredTasks(tasks);
  };

  // ✅ When tasks update from Redux, update displayed list
  useEffect(() => {
    setFilteredTasks(tasks);
  }, [tasks]);

  return (
    <>
      <div className="SearchForm">
        <SelectBox
          label="By Category"
          value={searchCategory}
          onChange={(e) => setSearchCategory(e.target.value)}
          options={["Learning", "Work", "Playing", "eating"]}
          className="SearchbyCategory"
        />

        <SelectBox
          label="By Priority"
          value={searchPriority}
          onChange={(e) => setSearchPriority(e.target.value)}
          options={["Low", "Mid", "High"]}
          className="SearchbyPriority"
        />

        <div className="SearchTitelForm">
          <input
            className="SearchbyTitle"
            type="text"
            value={searchInputName}
            onChange={(e) => setSearchInputName(e.target.value)}
            placeholder="Search by Title"
          />
          <button className="Searchbtn" onClick={handleSearchClick}>
            <img src={searchbtn} alt="searchbtn" />
          </button>
        </div>

        <button className="ResetBtn" onClick={handleResetFilters}>
          Reset Filters
        </button>
      </div>

      <div className="card-container">
        {filteredTasks.length === 0 ? (
          <p>No tasks found!</p>
        ) : (
          filteredTasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onComplete={() => dispatch(markComplete(task.id))}
              onDelete={() => dispatch(deleteTask(task.id))}
            />
          ))
        )}
      </div>
    </>
  );
}

export default DisplayAllTasks;
